// Local simulation. No iMIS hooks or network requests.
(()=>{const root=document.getElementById('working-panel'),content=document.getElementById('working-content'),wait=document.getElementById('working-wait'),error=document.getElementById('working-error'),status=document.getElementById('working-status'),label=document.getElementById('working-state');let timer=null,hasData=false;
function render(state){const busy=state==='initial'||state==='refresh';root.setAttribute('aria-busy',String(busy));root.classList.toggle('refreshing',state==='refresh');content.hidden=!hasData;content.inert=busy;wait.hidden=!busy;error.hidden=state!=='error';label.textContent=({initial:'Initial loading',refresh:'Refreshing',ready:'Ready',error:'Unable to load'})[state];document.querySelectorAll('[data-start]').forEach(b=>b.disabled=busy);document.getElementById('simulate-failure').disabled=busy;}
document.getElementById('loader-choice').addEventListener('change',e=>{const glyph=wait.querySelector('span');glyph.className=e.target.value;glyph.innerHTML=e.target.value.startsWith('section-loader-reassembly')?'<i></i><i></i><i></i><i></i>':e.target.value==='section-loader-aligning-rings'?'<i></i><i></i><i></i>':e.target.value.startsWith('section-loader-splitting-blocks')?'<i><b></b><b></b></i><i><b></b><b></b></i>':''});
function start(mode,forceSuccess=false){clearTimeout(timer);if(mode==='initial')hasData=false;else hasData=true;const fail=!forceSuccess&&document.getElementById('simulate-failure').checked;document.querySelector('#working-wait strong').textContent=mode==='refresh'?'Refreshing records…':'Loading records…';render(mode);status.textContent=mode==='initial'?'Loading records…':'Refreshing records. Previous results are temporarily unavailable for interaction.';timer=setTimeout(()=>{if(fail){hasData=false;render('error');status.textContent='Could not load the records. Retry is available.'}else{hasData=true;render('ready');status.textContent='Three example records loaded. No live data was requested.'}},document.getElementById('loader-choice').value.startsWith('section-loader-reassembly')?7200:1800)}
document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));document.getElementById('retry').onclick=()=>start('initial',true);document.getElementById('reset-demo').onclick=()=>{clearTimeout(timer);hasData=true;render('ready');status.textContent='Example reset.'};render('ready');hasData=true;render('ready');
document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const el=document.getElementById(b.dataset.copy);try{await navigator.clipboard.writeText(el.textContent);document.getElementById('copy-status').textContent='Copied.'}catch{const r=document.createRange();r.selectNodeContents(el);getSelection().removeAllRanges();getSelection().addRange(r);document.getElementById('copy-status').textContent='Selected. Press Ctrl+C.'}});
})();